import{_ as a,o as t,c as s,ae as i}from"./chunks/framework.Co1PSFSm.js";const p=JSON.parse('{"title":"Guía de Instalación para Usuarios","description":"","frontmatter":{},"headers":[],"relativePath":"user/index.md","filePath":"user/index.md"}'),n={name:"user/index.md"};function l(o,e,r,d,c,h){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="guia-de-instalacion-para-usuarios" tabindex="-1">Guía de Instalación para Usuarios <a class="header-anchor" href="#guia-de-instalacion-para-usuarios" aria-label="Permalink to &quot;Guía de Instalación para Usuarios&quot;">​</a></h1><h2 id="instalacion-desde-whmcs" tabindex="-1">Instalación desde WHMCS <a class="header-anchor" href="#instalacion-desde-whmcs" aria-label="Permalink to &quot;Instalación desde WHMCS&quot;">​</a></h2><p>Entra a <strong>Mi Portal → Mis Productos y Servicios → Detalles del Servicio</strong>. Verás un panel con el siguiente comando:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://api.hwperu.com/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --token</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dbp_saas_3070</span></span></code></pre></div><h3 id="flujo-de-instalacion" tabindex="-1">Flujo de Instalación <a class="header-anchor" href="#flujo-de-instalacion" aria-label="Permalink to &quot;Flujo de Instalación&quot;">​</a></h3><p>Ejecuta el comando en tu VPS como <code>root</code>.</p><ol><li><strong>Verificar dependencias:</strong> El instalador revisará si tienes <code>jq</code> y Docker instalados. Si faltan, se autoinstalarán.</li><li><strong>Identidad del Hardware:</strong> Se genera una huella única del hardware para seguridad.</li><li><strong>Autenticación:</strong> El agente se comunica con el API y descarga la imagen privada de despliegue.</li><li><strong>Despliegue:</strong> Se levanta el contenedor del agente y en aproximadamente 30 segundos aparecerá conectado en el panel web.</li></ol><h2 id="entendiendo-el-panel" tabindex="-1">Entendiendo el Panel <a class="header-anchor" href="#entendiendo-el-panel" aria-label="Permalink to &quot;Entendiendo el Panel&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Elemento</th><th style="text-align:left;">Función</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>HEALTH: 100%</strong></td><td style="text-align:left;">Puntaje de salud del agente. Baja si hay un problema o está offline.</td></tr><tr><td style="text-align:left;"><strong>OPERATIVO / OFFLINE</strong></td><td style="text-align:left;">Muestra en tiempo real si el servidor está conectado.</td></tr><tr><td style="text-align:left;"><strong>RTO</strong></td><td style="text-align:left;">Tiempo estimado de recuperación.</td></tr><tr><td style="text-align:left;"><strong>RPO</strong></td><td style="text-align:left;">Antigüedad del último backup.</td></tr></tbody></table><h2 id="como-usar-el-health-score" tabindex="-1">Cómo usar el Health Score <a class="header-anchor" href="#como-usar-el-health-score" aria-label="Permalink to &quot;Cómo usar el Health Score&quot;">​</a></h2><p>El Health Score se calcula en base a:</p><ul><li>Conexión actual (-50 puntos si está offline).</li><li>Si el último backup ocurrió hace más de 24 horas (-20 puntos).</li><li>Si la verificación de integridad mensual o semanal falla (-40 puntos).</li></ul>',12)])])}const g=a(n,[["render",l]]);export{p as __pageData,g as default};
